-- Tables the backup carries that test/fixtures/schema.sql doesn't define, copied from the live database (Oct 30, 2026),
-- so a restore keeps their keys and types. tools/restore.mjs runs this after schema.sql.
CREATE TABLE IF NOT EXISTS call_grades (id TEXT PRIMARY KEY, client_id TEXT NOT NULL, at TEXT, outcome TEXT DEFAULT '', seconds INTEGER DEFAULT 0, turns INTEGER DEFAULT 0, first_word_ms INTEGER DEFAULT 0, max_word_ms INTEGER DEFAULT 0, booked INTEGER DEFAULT 0, hangup_early INTEGER DEFAULT 0, misheard INTEGER DEFAULT 0, asked_twice INTEGER DEFAULT 0, offered_time INTEGER DEFAULT 0, offered_callback INTEGER DEFAULT 0, asked_person INTEGER DEFAULT 0, upset INTEGER DEFAULT 0, next_step INTEGER DEFAULT 0, spam INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS minute_overage (client_id TEXT, month TEXT, minutes INTEGER, cents INTEGER, invoiced TEXT, invoice_item TEXT, PRIMARY KEY (client_id, month));
CREATE TABLE IF NOT EXISTS line_interviews (id INTEGER PRIMARY KEY AUTOINCREMENT, client_id TEXT NOT NULL, number TEXT NOT NULL, phone TEXT NOT NULL, sid TEXT DEFAULT '', status TEXT DEFAULT 'calling', created TEXT, updated TEXT, result TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS line_bookings (id INTEGER PRIMARY KEY AUTOINCREMENT, client_id TEXT NOT NULL, start INTEGER NOT NULL, end INTEGER NOT NULL, name TEXT DEFAULT '', phone TEXT DEFAULT '', reason TEXT DEFAULT '', status TEXT DEFAULT 'booked', call_id TEXT DEFAULT '', say TEXT DEFAULT '', created TEXT, updated TEXT);
CREATE TABLE IF NOT EXISTS sms_brands (client_id TEXT PRIMARY KEY, messaging_sid TEXT DEFAULT '', status TEXT DEFAULT 'pending', updated TEXT);
CREATE TABLE IF NOT EXISTS a2p_reg (client_id TEXT PRIMARY KEY, status TEXT DEFAULT 'none', step TEXT DEFAULT '', form TEXT DEFAULT '{}', sids TEXT DEFAULT '{}', error TEXT DEFAULT '', tries INTEGER DEFAULT 0, created TEXT, updated TEXT);
CREATE TABLE IF NOT EXISTS biz_stripe (client_id TEXT PRIMARY KEY, account TEXT, ready INTEGER DEFAULT 0, checked TEXT, created TEXT);
CREATE TABLE IF NOT EXISTS app_settings (client_id TEXT PRIMARY KEY, avg_job INTEGER DEFAULT 0, win_rate INTEGER DEFAULT 30, updated TEXT);
CREATE TABLE IF NOT EXISTS biz_msgs (id INTEGER PRIMARY KEY AUTOINCREMENT, client_id TEXT NOT NULL, channel TEXT, thread TEXT, name TEXT DEFAULT '', text TEXT, dir TEXT DEFAULT 'in', at TEXT, by TEXT DEFAULT '', status TEXT DEFAULT 'new', ext_id TEXT DEFAULT '');
